args <- commandArgs(trailingOnly = TRUE); value <- function(flag, default = NULL) { i <- match(flag, args); if (is.na(i)) default else if (i == length(args)) stop("Missing value after ", flag, call. = FALSE) else args[i + 1L] }
if (!"--authorize-execution" %in% args || !identical(Sys.getenv("EPIPLUME_ALLOW_HYSPLIT_EXECUTION"), "true")) stop("Execution requires --authorize-execution and EPIPLUME_ALLOW_HYSPLIT_EXECUTION=true.", call. = FALSE)
config <- value("--config"); manifest_path <- value("--manifest"); if (is.null(config) || is.null(manifest_path)) stop("--config and --manifest are required.", call. = FALSE)
source("R/read_facility_exchange_config.R"); source("R/build_pipeline_run_selection.R"); source("R/validate_hysplit_manifest_row.R"); source("R/resolve_hysplit_meteorology.R"); source("R/build_hysplit_run_spec.R"); source("R/resolve_hysplit_installation.R"); source("R/run_hysplit_manifest_row.R"); source("R/classify_manifest_execution_state.R"); source("R/update_manifest_execution_ledger.R"); source("R/read_facility_exchange_inputs.R"); source("R/simulate_facility_network.R"); source("R/simulate_facility_observations.R"); source("R/validate_facilities.R"); source("R/validate_observations.R"); source("R/run_hysplit_manifest_subset.R")
cfg <- read_facility_exchange_config(config); manifest <- utils::read.csv(manifest_path, stringsAsFactors = FALSE); ids <- value("--run-ids"); selected <- if (is.null(ids)) manifest else build_pipeline_run_selection(manifest, ids); states <- classify_manifest_execution_state(selected, cfg); print(as.data.frame(table(states$execution_state), stringsAsFactors = FALSE)); result <- tryCatch(run_hysplit_manifest_subset(manifest, cfg, run_ids = ids, workers = as.integer(value("--workers", 1L)), continue_on_error = !"--stop-on-error" %in% args, retry_failed = "--retry-failed" %in% args, reuse_completed = !"--no-reuse-completed" %in% args, parse_outputs = !"--no-parse" %in% args, extract_receptors = !"--no-extract-receptors" %in% args), error = function(e) { message("ERROR: ", conditionMessage(e)); quit(save = "no", status = 1L) }); print(result$state_summary); if (any(grepl("failed|blocked|invalid", names(result$state_summary)))) quit(save = "no", status = 1L)
